SELECT (SELECT name FROM warehouses w WHERE w.warehouse_id = s.warehouse_id) AS wn, SUM(CASE WHEN on_hand_units = 0 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS r FROM inventory_snapshots s WHERE s.snapshot_date >= DATE '2026-01-01' AND s.snapshot_date <= DATE '2026-10-31' GROUP BY s.warehouse_id ORDER BY r DESC LIMIT 1
